{
  "headline": "FDA's records trace our supply to a plant classified OAI 23 days before the shortage posting",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA first posted the carboplatin shortage on 2023-04-28 and it has remained current for 42 months as of 2026-10-21.",
      "cites": ["E31", "D12"]
    },
    {
      "text": "The Accord Healthcare product on the shortage list uses Intas Pharmaceuticals Limited as a registered manufacturing plant.",
      "cites": ["E21", "E20"]
    },
    {
      "text": "FDA inspection 1191818 at Intas ended 2022-12-02 and was classified OAI, with the classification letter dated 2023-04-05 — 23 days before the shortage posting.",
      "cites": ["E16", "D8"]
    },
    {
      "text": "An import alert 66-40 for Intas was published 2023-06-01 (34 days after posting) and again 2023-11-14 (200 days after posting), and a Warning Letter was issued 2023-07-28 (91 days after posting).",
      "cites": ["D5", "D7", "D6"]
    },
    {
      "text": "Our Corvale East site holds two NDCs: Teva (0703-4239-01) manufactured by PHARMACHEMIE BV and Apotex (60505-6282-1) manufactured by Teyro Labs Private Limited.",
      "cites": ["E1", "E9", "E2", "E11"]
    },
    {
      "text": "Teyro Labs received a VAI classification on 2025-11-12, while PHARMACHEMIE BV has no FDA action shown in the evidence.",
      "cites": ["E10", "E11", "E9"]
    },
    {
      "text": "The rule‑ranked transfer option moves 26 units from Corvale East (18 days on hand) to Corvale Lakeside (1.9 days on hand), bringing Lakeside to 14 days.",
      "cites": ["D9", "D1", "D3"]
    }
  ]
}
